import { Auth } from '../../model/public_types';
import { ErrorFactory, FirebaseError } from '@firebase/util';
import { AuthInternal } from '../../model/auth';
import {
  _DEFAULT_AUTH_ERROR_FACTORY,
  AuthErrorCode,
  AuthErrorParams,
  prodErrorMap,
  ErrorMapRetriever
} from '../errors';
